-- RFN Part Catalog dashboard upgrade
-- Run once in Supabase SQL Editor.

alter table public.inventory add column if not exists section_key text default '';
alter table public.inventory add column if not exists section_name text default '';
alter table public.inventory add column if not exists diagram_image_url text default '';
alter table public.inventory add column if not exists image_url text default '';

create index if not exists inventory_bike_section_idx on public.inventory (bike_id, section_key);
create index if not exists inventory_part_number_idx on public.inventory (part_number);

-- Public image bucket used by the admin image uploader.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'catalog-images',
  'catalog-images',
  true,
  8388608,
  array['image/jpeg','image/png','image/webp','image/gif']
)
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

create table if not exists public.catalog_sections (
  id uuid primary key default gen_random_uuid(),
  bike_id uuid not null references public.bikes(id) on delete cascade,
  section_key text not null,
  section_name text not null default '',
  diagram_image_url text not null default '',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (bike_id, section_key)
);
create index if not exists catalog_sections_bike_idx on public.catalog_sections (bike_id, sort_order, section_key);
alter table public.catalog_sections enable row level security;
